arguments.content:
:root {
  --bg: #141018;
  --ink: #f4 e9dd;
  --ink: #f4e9dd;
  --warm: #ffcf9e;
  --glow: #ffd9a8;
  --panel: rgba(24, 18, 28, 0.72);
  --panel-edge: rgba(255, 207, 158, 0.18);
  --shadow: 0 12px 40px rgba(0, 0, 0, 0.45);
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: radial-gradient(120% 120% at 50% 0%, #241a28 0%, #120d16 55%, #0b0810 100%);
  color: var(--ink);
  font-family: "Segoe UI", system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
}

#app {
  position: fixed;
  inset: 0;
  display: block;
}

canvas {
  display: block;
  width: 100%;
  height: 100%;
  touch-action: none;
}

/* ---------- Overlay / start screen ---------- */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 40;
  display: grid;
  place-items: center;
  background:
    radial-gradient(120% 120% at 50% 20%, rgba(60, 40, 70, 0.55), rgba(10, 7, 14, 0.92)),
    #0b0810;
  transition: opacity 0.9s var(--ease), visibility 0.9s;
}

.overlay.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.card {
  width: min(420px, 86vw);
  padding: 40px 36px;
  text-align: center;
  border-radius: 22px;
  background: linear-gradient(160deg, rgba(40, 30, 48, 0.9), rgba(20, 14, 26, 0.92));
  border: 1px solid var(--panel-edge);
  box-shadow: var(--shadow);
  backdrop-filter: blur(8px);
}

.kicker {
  display: inline-block;
  font-size: 11px;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--warm);
  opacity: 0.8;
  margin-bottom: 14px;
}

h1 {
  font-size: 34px;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: var(--ink);
  text-shadow: 0 0 24px rgba(255, 207, 158, 0.25);
}

.sub {
  margin-top: 8px;
  font-size: 14px;
  color: rgba(244, 233, 221, 0.6);
}

.enter-btn {
  margin-top: 26px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  width: 100%;
  padding: 14px 18px;
  font-size: 15px;
  font-weight: 600;
  color: #221a12;
  background: linear-gradient(135deg, #ffdfb0, #ffbf80);
  border: none;
  border-radius: 14px;
  cursor: pointer;
  box-shadow: 0 8px 24px rgba(255, 180, 110, 0.3);
  transition: transform 0.3s var(--ease), box-shadow 0.3s var(--ease);
}

.enter-btn:hover {
  transform: translateY(-2px);
  box-shadow: 0 12px 32px rgba(255, 180, 110, 0.45);
}

.enter-btn:active {
  transform: translateY(0);
}

.play-dot {
  width: 0;
  height: 0;
  border-left: 10px solid #221a12;
  border-top: 6px solid transparent;
  border-bottom: 6px solid transparent;
}

.hint {
  margin-top: 20px;
  font-size: 12px;
  color: rgba(244, 233, 221, 0.42);
  line-height: 1.6;
}

/* ---------- HUD ---------- */
.hud {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 20;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: 18px 22px;
  pointer-events: none;
  transition: opacity 0.6s var(--ease);
}

.hud.hidden {
  opacity: 0;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.brand-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--warm);
  box-shadow: 0 0 12px var(--warm);
  animation: pulse 2.6s ease-in-out infinite;
}

@keyframes pulse {
  0%,
  100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}

.clock {
  font-variant-numeric: tabular-nums;
  font-size: 13px;
  color: rgba(244, 233, 221, 0.7);
  background: var(--panel);
  border: 1px solid var(--panel-edge);
  padding: 7px 12px;
  border-radius: 999px;
  backdrop-filter: blur(6px);
}

/* ---------- Controls ---------- */
.controls {
  position: fixed;
  bottom: 22px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 20;
  display: flex;
  gap: 10px;
  padding: 8px;
  background: var(--panel);
  border: 1px solid var(--panel-edge);
  border-radius: 16px;
  backdrop-filter: blur(10px);
  box-shadow: var(--shadow);
  transition: opacity 0.6s var(--ease), transform 0.6s var(--ease);
}

.controls.hidden {
  opacity: 0;
  transform: translateX(-50%) translateY(12px);
  pointer-events: none;
}

.ctrl-btn {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 10px 14px;
  background: transparent;
  border: none;
  color: var(--ink);
  border-radius: 10px;
  cursor: pointer;
  transition: background 0.2s, color 0.2s;
  min-width: 62px;
}

.ctrl-btn:hover {
  background: rgba(255, 207, 158, 0.12);
  color: var(--warm);
}

.ctrl-btn.active .ctrl-icon {
  color: var(--warm);
  text-shadow: 0 0 12px var(--warm);
}

.ctrl-icon {
  font-size: 18px;
  line-height: 1;
}

.ctrl-label {
  font-size: 11px;
  letter-spacing: 0.04em;
  opacity: 0.75;
}

/* ---------- Caption ---------- */
.caption {
  position: fixed;
  bottom: 92px;
  left: 50%;
  transform: translateX(-50%);
  z-index: 20;
  padding: 8px 16px;
  font-size: 13px;
  color: var(--glow);
  background: var(--panel);
  border: 1px solid var(--panel-edge);
  border-radius: 999px;
  backdrop-filter: blur(6px);
  opacity: 0;
  transition: opacity 0.4s var(--ease);
  pointer-events: none;
  white-space: nowrap;
}

.caption.show {
  opacity: 1;
}

/* ---------- Self-test console ---------- */
#selftest {
  position: fixed;
  bottom: 8px;
  left: 8px;
  z-index: 60;
  font-family: ui-monospace, monospace;
  font-size: 11px;
  color: #9fe9a0;
  background: rgba(0, 0, 0, 0.6);
  padding: 6px 10px;
  border-radius: 6px;
  max-width: 320px;
  display: none;
}

