// Lighten/darken a THREE.Color by a relative amount.
function shade(color, amt) {
  const c = color.clone();
  const h = c.toHSV();
  h.v = clamp(h.v + amt, 0, 1);
  return new THREE.Color().fromHSV(h.h, h.s, h.v);
}

